// Este nodo simula filas leídas desde Excel.
// En una implementación real, reemplazar por Google Drive/OneDrive + Spreadsheet File.
const filasExcel = [
  {
    "DNI": "42.345.678",
    "Apellido y nombre": "Suarez Mateo",
    "Fecha nac.": "12/03/2014",
    "Sexo": "M",
    "Barrio": "Belgrano",
    "Centro": "Centro Ninez Norte",
    "Tipo de centro": "ninez",
    "Escolarizado": "SI",
    "Consumo": "no",
    "Violencia familiar": "No"
  },
  {
    "Documento": "30111222",
    "Nombre completo": "Rodrigo Aguirre",
    "Nacimiento": "1989-04-03",
    "Género": "M",
    "Zona": "Almagro",
    "Dispositivo": "Centro de Dia Almagro",
    "Modalidad": "dia",
    "Tiene CUD": "sí",
    "Situación de consumo": "S",
    "Violencia": "no"
  },
  {
    "Nro DNI": "",
    "Persona": "Registro sin DNI",
    "Fecha de nacimiento": "10/10/2010",
    "Centro": "Centro Ninez Sur",
    "Tipo dispositivo": "ninez"
  },
  {
    "Doc": "42-345-678",
    "Nombre": "Suarez Mateo",
    "Nacimiento": "2014-03-12",
    "Centro": "Centro Ninez Norte",
    "Tipo de centro": "ninez",
    "Escolarizado": "si"
  }
];

return filasExcel.map((fila, index) => ({
  json: {
    ...fila,
    fuente_archivo: "excel_historico_demo.xlsx",
    numero_fila: index + 2
  }
}));

const rows = $input.all();

function limpiarTexto(valor) {
  if (valor === undefined || valor === null) return "";
  return String(valor).trim();
}

function normalizarDNI(valor) {
  return limpiarTexto(valor).replace(/[.\-\s]/g, "");
}

function normalizarSiNo(valor) {
  const v = limpiarTexto(valor).toLowerCase();
  if (["si", "sí", "s", "yes", "y", "1", "true"].includes(v)) return "sí";
  if (["no", "n", "0", "false"].includes(v)) return "no";
  return "";
}

function normalizarFecha(valor) {
  if (!valor) return "";
  const texto = limpiarTexto(valor);

  if (/^\d{4}-\d{2}-\d{2}$/.test(texto)) return texto;

  const partes = texto.split("/");
  if (partes.length === 3) {
    const [dia, mes, anio] = partes;
    return `${anio.padStart(4, "20")}-${mes.padStart(2, "0")}-${dia.padStart(2, "0")}`;
  }

  const fecha = new Date(texto);
  if (!isNaN(fecha)) return fecha.toISOString().slice(0, 10);

  return "";
}

function tomarCampo(row, posiblesNombres) {
  for (const nombre of posiblesNombres) {
    if (row[nombre] !== undefined && row[nombre] !== null && row[nombre] !== "") {
      return row[nombre];
    }
  }
  return "";
}

return rows.map(item => {
  const row = item.json;

  const dni = normalizarDNI(tomarCampo(row, [
    "DNI", "Doc", "Documento", "Nro DNI", "Nro. DNI", "Número de documento"
  ]));

  const nombreCompleto = limpiarTexto(tomarCampo(row, [
    "Apellido y nombre", "Nombre completo", "Persona", "Nombre"
  ]));

  const fechaNacimiento = normalizarFecha(tomarCampo(row, [
    "Fecha de nacimiento", "Nacimiento", "Fecha nac.", "F. Nac"
  ]));

  const sexo = limpiarTexto(tomarCampo(row, ["Sexo", "Género", "Genero"])).toUpperCase();

  const barrio = limpiarTexto(tomarCampo(row, [
    "Barrio", "Zona", "Domicilio/Barrio"
  ]));

  const centro = limpiarTexto(tomarCampo(row, [
    "Centro", "Dispositivo", "Nombre del centro"
  ]));

  const tipoCentro = limpiarTexto(tomarCampo(row, [
    "Tipo de centro", "Tipo dispositivo", "Modalidad"
  ])).toLowerCase();

  const escolarizado = normalizarSiNo(tomarCampo(row, [
    "Escolarizado", "¿Escolarizado?", "Va a la escuela"
  ]));

  const cud = normalizarSiNo(tomarCampo(row, [
    "CUD", "Tiene CUD", "¿Tiene CUD?"
  ]));

  const consumo = normalizarSiNo(tomarCampo(row, [
    "Consumo", "Consumo activo", "Situación de consumo", "¿Consumo?"
  ]));

  const violencia = normalizarSiNo(tomarCampo(row, [
    "Violencia", "Violencia familiar", "Situación de violencia"
  ]));

  const errores = [];
  if (!dni) errores.push("DNI vacío");
  if (dni && !/^\d{7,9}$/.test(dni)) errores.push("DNI con formato inválido");
  if (!nombreCompleto) errores.push("Falta nombre");
  if (!centro) errores.push("Falta centro");
  if (!tipoCentro) errores.push("Falta tipo de centro");

  return {
    json: {
      dni,
      nombre_completo: nombreCompleto,
      fecha_nacimiento: fechaNacimiento,
      sexo,
      barrio,
      centro,
      tipo_centro: tipoCentro,
      escolarizado,
      cud,
      consumo_activo: consumo,
      violencia_familiar: violencia,
      estado: "activo",
      fuente_archivo: row.fuente_archivo || "Excel histórico",
      numero_fila: row.numero_fila || null,
      fecha_migracion: new Date().toISOString(),
      valido: errores.length === 0,
      errores: errores.join("; "),
      registro_original: row
    }
  };
});

// Deduplicación por DNI dentro de la misma ejecución.
// Si el mismo DNI aparece dos veces, conserva el último registro normalizado.
const map = new Map();

for (const item of $input.all()) {
  const dni = item.json.dni || `sin_dni_${item.json.numero_fila}`;
  map.set(dni, item.json);
}

return Array.from(map.values()).map(row => ({ json: row }));

// Demo de carga incremental ficticia usando memoria interna del workflow.
// En producción, reemplazar por Postgres/Supabase:
// - UPSERT personas usando dni como clave única.
// - UPSERT vinculos usando dni + centro como clave compuesta.

const sd = $getWorkflowStaticData("global");
if (!sd.migracion) {
  sd.migracion = {
    personas: {},
    vinculos: {},
    historial: []
  };
}

const salida = [];

for (const item of $input.all()) {
  const r = item.json;

  const personaKey = r.dni;
  const vinculoKey = `${r.dni}__${r.centro}`;

  const personaYaExistia = Boolean(sd.migracion.personas[personaKey]);
  const vinculoYaExistia = Boolean(sd.migracion.vinculos[vinculoKey]);

  sd.migracion.personas[personaKey] = {
    dni: r.dni,
    nombre_completo: r.nombre_completo,
    fecha_nacimiento: r.fecha_nacimiento,
    sexo: r.sexo,
    barrio: r.barrio,
    actualizado_en: r.fecha_migracion
  };

  sd.migracion.vinculos[vinculoKey] = {
    dni: r.dni,
    centro: r.centro,
    tipo_centro: r.tipo_centro,
    estado: r.estado,
    escolarizado: r.escolarizado,
    cud: r.cud,
    consumo_activo: r.consumo_activo,
    violencia_familiar: r.violencia_familiar,
    fuente_archivo: r.fuente_archivo,
    actualizado_en: r.fecha_migracion
  };

  sd.migracion.historial.push({
    dni: r.dni,
    centro: r.centro,
    evento: personaYaExistia ? "actualización/consolidación" : "alta inicial",
    fecha: r.fecha_migracion,
    fuente_archivo: r.fuente_archivo,
    numero_fila: r.numero_fila
  });

  salida.push({
    json: {
      ...r,
      accion_persona: personaYaExistia ? "actualizada" : "creada",
      accion_vinculo: vinculoYaExistia ? "actualizado" : "creado",
      carga_incremental: true
    }
  });
}

return salida;

// Registros rechazados para revisión manual.
// En producción, reemplazar por Google Sheets, Slack o tabla migracion_errores.
return $input.all().map(item => ({
  json: {
    estado_revision: "pendiente",
    motivo_error: item.json.errores,
    dni: item.json.dni,
    nombre_completo: item.json.nombre_completo,
    centro: item.json.centro,
    fuente_archivo: item.json.fuente_archivo,
    numero_fila: item.json.numero_fila,
    registro_original: item.json.registro_original
  }
}));

const items = $input.all();

return [{
  json: {
    etapa: "reporte_final_cargados",
    mensaje: "Pipeline independiente ejecutado. Los registros validos fueron cargados en la base ficticia interna del workflow.",
    registros_cargados: items.length,
    fecha_reporte: new Date().toISOString(),
    nota: "Para produccion se reemplaza la base ficticia por Supabase/Postgres. Para el TP, este flujo demuestra heterogeneidad, normalizacion, deduplicacion, incrementalidad y auditoria."
  }
}];

const items = $input.all();

return [{
  json: {
    etapa: "reporte_final_errores",
    mensaje: "Pipeline independiente ejecutado. Los registros invalidos quedaron separados para revision manual.",
    registros_con_error: items.length,
    fecha_reporte: new Date().toISOString(),
    nota: "Los errores no detienen el flujo completo, que es uno de los requisitos centrales del TP."
  }
}];
